"""Native effective-value/weapon-rule regression on a disposable Android emulator.

Run Test-StandaloneAndroid.py for the same APK first. Pass its arguments plus
--fixture <weapon-rules-ui.json> generated by GrimList.Tests --weapon-rules-only.
Imports that synthetic faction through the public file picker; never edits the DB.
Requires Pillow for checking the actual rendered highlight colour.
"""
import json
import pathlib
import re
import sys
import time
from PIL import Image

fixture_index = sys.argv.index('--fixture')
fixture = pathlib.Path(sys.argv[fixture_index + 1]).resolve()
del sys.argv[fixture_index:fixture_index + 2]
helper = pathlib.Path(__file__).with_name('Test-StandaloneAndroid.py')
context = {'__name__': '__weapon_rules_checks__'}
exec(compile(helper.read_text(encoding='utf-8').split("check('APK installs'")[0], str(helper), 'exec'), context)
previous = json.loads((context['args'].output / 'results.json').read_text(encoding='utf-8'))
if previous['apk_sha256'] != context['results']['apk_sha256'] or 'Reopened army still validates' not in previous['checks']:
    raise RuntimeError('Run baseline acceptance for this APK first.')
context['results'] = previous
adb, check, dump, find, wait, tap, screenshot = (context[n] for n in
    ('adb', 'check', 'dump', 'find', 'wait', 'tap', 'screenshot'))


def top():
    for _ in range(8):
        adb('shell', 'input', 'swipe', '20', '650', '20', '2100', '100')


def native_tap(node):
    x1, y1, x2, y2 = map(int, re.findall(r'\d+', node.get('bounds')))
    adb('shell', 'input', 'tap', str((x1 + x2) // 2), str((y1 + y2) // 2))
    time.sleep(1)


def value(control, expected, modified):
    top()
    for _ in range(15):
        ui = dump()
        node = find(ui, control)
        if node is not None:
            check(control + ': final value', node.get('text') == expected and '→' not in node.get('text', ''))
            screenshot(control)
            box = tuple(map(int, re.findall(r'\d+', node.get('bounds'))))
            crop = Image.open(context['args'].output / (control + '.png')).convert('RGB').crop(box)
            gold = sum(all(abs(a - b) <= 20 for a, b in zip(pixel, (244, 213, 141))) for pixel in crop.getdata())
            check(control + ': rendered highlight', (gold > 3) == modified)
            return
        adb('shell', 'input', 'swipe', '20', '1700', '20', '1050', '200')
    raise AssertionError('Missing value ' + control)


def keywords():
    top()
    found = set()
    for _ in range(10):
        ui = dump()
        found.update(n.get('resource-id').split(':id/keyword-', 1)[1] for n in ui.iter('node')
                     if ':id/keyword-' in n.get('resource-id', ''))
        adb('shell', 'input', 'swipe', '20', '1900', '20', '850', '250')
    return found


def import_fixture(path):
    adb('push', str(path), '/sdcard/Download/' + path.name)
    tap('menu'); tap('menu-library'); tap('import-library', scroll=True)
    ui = dump('weapon-fixture-picker')
    drawer = next((n for n in ui.iter('node') if n.get('content-desc') in
                   ('Show roots', 'Open navigation drawer')), None)
    if drawer is not None:
        native_tap(drawer)
        tap('Downloads')
    ui = dump()
    document = next(n for n in ui.iter('node') if n.get('text') == path.name
                    or n.get('content-desc', '').startswith(path.name + ','))
    native_tap(document)
    wait('apply-library', 'weapon-fixture-preview'); tap('apply-library', scroll=True)


import_fixture(fixture)
tap('menu'); tap('menu-new'); tap('Test', scroll=True)
wait('army-name', 'weapon-rule-setup')
tap('army-name'); adb('shell', 'input', 'text', 'WeaponRulesAcceptance'); adb('shell', 'input', 'keyevent', '4')
tap('detachment-Host', scroll=True); tap('create-army', scroll=True)
wait('unit-search', 'weapon-rule-army')
ui = dump()
add = next(n.get('resource-id').split(':id/', 1)[1] for n in ui.iter('node') if ':id/add-unit-' in n.get('resource-id', ''))
tap(add)
ui = dump()
entry = next(n.get('resource-id').split(':id/', 1)[1] for n in ui.iter('node') if ':id/roster-entry-' in n.get('resource-id', ''))
tap(entry)
value('effective-stat-T', '11', True)
value('effective-stat-M', '6"', False)
value('effective-weapon-GUN-S', '6', True)
value('effective-weapon-GUN-A', '2', False)
top(); tap('enhancement-Mobile bearer', scroll=True)
granted = keywords()
check('Android enhancement and detachment weapon keywords', {'ASSAULT', 'SUSTAINED HITS 1', 'HEAVY'} <= granted)
top(); tap('enhancement-Mobile bearer', scroll=True)
remaining = keywords()
check('Android enhancement removal preserves detachment effect', 'ASSAULT' not in remaining and 'SUSTAINED HITS 1' in remaining)
tap('menu'); tap('menu-rules'); tap('Host', scroll=True); tap('remove-detachment-Host', scroll=True)
tap('back'); tap(entry)
remaining = keywords()
check('Android detachment removal restores source keywords', 'SUSTAINED HITS 1' not in remaining and 'HEAVY' in remaining)

# Generated from the real imported library, not rewritten synthetic rule wording.
source_fixture = fixture.with_name('source-weapon-rules-ui.json')
import_fixture(source_fixture)
for faction, detachment, unit, upgrade in (
        ('Necrons', 'Skyshroud Spearhead', 'Lokhust Destroyers', 'Deepening Madness'),
        ('Adepta Sororitas', 'Bringers of Flame', 'Battle Sisters Squad', None)):
    tap('menu'); tap('menu-new'); tap(faction, scroll=True)
    wait('army-name', 'source-weapon-setup')
    tap('detachment-' + detachment, scroll=True); tap('create-army', scroll=True)
    wait('unit-search', 'source-weapon-army')
    tap('unit-search'); adb('shell', 'input', 'text', unit.replace(' ', '%s'))
    adb('shell', 'input', 'keyevent', '4')
    time.sleep(1)
    ui = dump()
    add = next(n.get('resource-id').split(':id/', 1)[1] for n in ui.iter('node')
               if ':id/add-unit-' in n.get('resource-id', ''))
    tap(add)
    ui = dump()
    entry = next(n.get('resource-id').split(':id/', 1)[1] for n in ui.iter('node')
                 if ':id/roster-entry-' in n.get('resource-id', ''))
    tap(entry)
    if upgrade:
        tap('enhancement-' + upgrade, scroll=True)
    check(unit + ': source Assault rendered', 'ASSAULT' in {k.upper() for k in keywords()})
    top(); tap('menu'); tap('menu-mode')
    check(unit + ': play-mode Assault rendered', 'ASSAULT' in {k.upper() for k in keywords()})
    top(); tap('menu'); tap('menu-mode')
    if upgrade:
        top(); tap('enhancement-' + upgrade, scroll=True)
    else:
        tap('menu'); tap('menu-rules'); tap(detachment, scroll=True)
        tap('remove-detachment-' + detachment, scroll=True)
        tap('back'); tap(entry)
    check(unit + ': source removal updates display', 'ASSAULT' not in {k.upper() for k in keywords()})
print('Android weapon-rule rendering regression complete.', flush=True)
